INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85082, 'spa', 'Aclarar por escrito', 'Clarificar o explicar mediante la escritura; hacer un texto legible y distinto. Moisés ''explicó'' (בֵּאֵר) la ley en Moab (Deuteronomio 1:5). La ley debía inscribirse en piedras ''haciéndola bien clara'' (Deuteronomio 27:8). A Habacuc se le ordena escribir la visión y ''hacerla legible'' en tablillas para que el lector pueda correr (Habacuc 2:2). El enfoque es pedagógico y comunicativo: asegurar que el mensaje sea accesible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85083, 'spa', 'Pozo, cisterna (fuente de agua excavada) — un pozo cavado en la tierra para acce', 'Pozo, cisterna (fuente de agua excavada) — un pozo cavado en la tierra para acceder al agua (o en Gn 14:10, al betún). Es el pozo patriarcal de encuentro y disputa: Abraham en Beerseba (Gn 21:25-30), Isaac en Rejobot (Gn 26:22), Jacob en Harán (Gn 29:2-3). Números 21:17-18 conserva un antiguo ''Cántico del Pozo'', y Proverbios emplea la imagen como metáfora de la esposa (Pr 5:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85090, 'spa', 'Fosa (de destrucción o peligro moral) — una fosa concebida como trampa o lugar d', 'Fosa (de destrucción o peligro moral) — una fosa concebida como trampa o lugar de destrucción, que extiende el sentido literal de profundidad y encierro hacia la metáfora. En el Salmo 55:23, Dios arrojará a los impíos a la ''fosa de destrucción'' (בְּאֵר שַׁחַת), y Proverbios 23:27 advierte que la adúltera es ''fosa profunda''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85096, 'spa', 'Cisterna o pozo', 'Cisterna, foso o pozo excavado para almacenar agua. En 2 Samuel 23:15–16 la palabra designa el pozo de Belén junto a la puerta, mientras que en Jeremías 2:13 aparece como «cisternas rotas» en una devastadora metáfora del abandono de Israel al Dios vivo. El sentido concreto de receptáculo de agua se mantiene uniforme en todas las apariciones bíblicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85100, 'spa', 'Ciudad gabaonita benjaminita', 'Nombre propio de lugar, Beerot (בְּאֵרוֹת, ''pozos''), ciudad de la confederación gabaonita-hevea asignada a la tribu de Benjamín. Josué 9:17 la enumera entre las cuatro ciudades gabaonitas que engañaron a Israel para obtener un tratado de paz. Josué 18:25 la ubica en la heredad de Benjamín. En 2 Samuel 4:2 se identifica como patria de Recab y Baaná. Los censos postexílicos de Esdras 2:25 y Nehemías 7:29 confirman la pervivencia de su comunidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85102, 'spa', 'Pozo en el Néguev', 'Un pozo en el desierto del Néguev donde Agar se encontró con el Ángel del Señor y llamó a Dios ''el Viviente que me ve'' (Génesis 16:14). El lugar quedó asociado con Isaac, quien vivió allí cuando se casó con Rebeca (Génesis 24:62) y después de la muerte de Abraham (Génesis 25:11). El nombre preserva la teología de la mirada divina: Dios ve al afligido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85103, 'spa', 'Beerseba (ciudad) — nombre propio de una ciudad en el desierto del Neguev, límit', 'Beerseba (ciudad) — nombre propio de una ciudad en el desierto del Neguev, límite sur tradicional de Israel. Fundada en el período patriarcal mediante la excavación de un pozo y el juramento de Abraham con Abimelec (Gn 21:14, 31-33), y reafirmada por Isaac (Gn 26:23, 33). Aparece en la fórmula ''desde Dan hasta Beerseba'' (Jue 20:1; 2 S 17:11) para designar toda la tierra prometida. También es el punto de partida de la huida de Elías al desierto (1 R 19:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85119, 'spa', 'Gentilicio de Beerot', 'Adjetivo gentilicio (בְּאֵרֹתִי) que identifica a una persona como habitante de Beerot en Benjamín. Cuatro de las cinco apariciones (2 Sam 4:2, 3, 5, 9) se refieren a Recab y Baaná, asesinos de Is-boset, cuyo origen geográfico resulta narrativamente significativo: 2 Samuel 4:3 señala que los beerotitas habían huido a Guitaim. La quinta mención (2 Sam 23:37) designa a Naharai, valiente de David.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85120, 'spa', 'Apestar, emitir mal olor (Qal) — La raíz Qal básica describe la putrefacción lit', 'Apestar, emitir mal olor (Qal) — La raíz Qal básica describe la putrefacción literal: el maná dejado de un día para otro ''crió gusanos y apestó'' (Éx 16:20), el Nilo azotado por la plaga ''apestaría'' con peces muertos (Éx 7:18), y la tierra de Egipto apestó por montones de ranas muertas (Éx 8:14). Isaías advierte que los peces ''apestarán por falta de agua'' (Is 50:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85121, 'spa', 'Hacer odioso, desprestigiar (Hifil, figurado) — La raíz Hifil con fuerza figurat', 'Hacer odioso, desprestigiar (Hifil, figurado) — La raíz Hifil con fuerza figurativa aparece cuando los hijos de Jacob temían haberse hecho ''odiosos'' ante los cananeos (Gn 34:30), o cuando los malvados se hacen ''detestables'' por su conducta vergonzosa (Pr 13:5). Las glosas multilingües muestran el español ''hediondo'' y el francés ''odieux'' rastreando el aspecto de desgracia social.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85123, 'spa', 'Hacerse odioso a sí mismo (Hitpael) — El Hitpael aparece una sola vez cuando los', 'Hacerse odioso a sí mismo (Hitpael) — El Hitpael aparece una sola vez cuando los amonitas ''se hicieron odiosos'' ante David (1 Cr 19:6), usando la raíz reflexivo-intensiva para enfatizar su desgracia autoinfligida deliberada al insultar a los mensajeros de David.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85124, 'spa', 'Hacer apestar (Hifil, literal) — El Hifil con significado literal es causativo', 'Hacer apestar (Hifil, literal) — El Hifil con significado literal es causativo: las moscas muertas ''hacen heder el ungüento del perfumista'' (Ec 10:1), o las heridas del salmista ''se infectan y hieden'' por su necedad (Sal 38:5). Notablemente, el maná ''no hedió'' cuando se guardó para el sábado (Éx 16:24), mostrando la suspensión divina de la descomposición natural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85125, 'spa', 'Hacerse odioso, aborrecible (Nifal) — La raíz Nifal denota volverse odioso ante ', 'Hacerse odioso, aborrecible (Nifal) — La raíz Nifal denota volverse odioso ante la estimación de alguien. Israel ''se hizo odioso'' ante los filisteos tras las victorias de Saúl (1 S 13:4), los amonitas ''se habían hecho odiosos'' ante David (2 S 10:6), y Absalón deliberadamente ''se hizo odioso'' ante su padre al acostarse públicamente con las concubinas (2 S 16:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85137, 'spa', 'Hedor de juicio', 'El olor fétido de cadáveres y descomposición tras el juicio divino. Isaías profetiza que los cuerpos de los muertos emitirán hedor (Isaías 34:3). Joel describe la pestilencia que se eleva de las langostas muertas (Joel 2:20). Amós recuerda cómo Dios envió peste y ''el hedor de vuestros campamentos subió a vuestras narices'' (Amós 4:10). El término subraya la dimensión olfativa del juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85141, 'spa', 'Bebai (nombre propio)', 'Nombre personal que designa al ancestro de una familia prominente en la comunidad postexílica. Los «hijos de Bebai» aparecen en el censo de exiliados que regresaron (Esd 2:11; Neh 7:16), en la caravana con Esdras (Esd 8:11), y entre quienes repudiaron a sus esposas extranjeras (Esd 10:28). El propio Bebai selló el pacto de Nehemías (Neh 10:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85142, 'spa', 'Babilonia', 'La antigua capital de Babilonia sobre el Éufrates (acadio Bab-ilim, ''puerta de dios''), que funciona como referente geográfico y como símbolo teológico. Escenario de la narrativa primordial de la torre (Gn 10:10; 11:9), sede del imperio de Nabucodonosor que destruyó Jerusalén y deportó a Judá (2 Re 24-25), y blanco de oráculos proféticos de perdición (Is 13; Jer 50-51). Transliterado universalmente en todas las lenguas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85153, 'spa', 'Nombre propio que designa la ciudad y el imperio mesopotámico a orillas del Éufr', 'Nombre propio que designa la ciudad y el imperio mesopotámico a orillas del Éufrates, presente en las secciones arameas de Daniel y Esdras como centro político donde los exiliados judíos vivían bajo Nabucodonosor y sus sucesores (Dn 2:12; Esd 5:12-14). En español se traduce como ''Babilonia''. El nombre porta una profunda resonancia teológica: desde la torre de Babel (Gn 11) hasta el exilio, simboliza la arrogancia humana, la opresión imperial y la certeza del juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85158, 'spa', 'Actuar traidoramente, traicionar — obrar con deslealtad hacia Dios, un cónyuge o', 'Actuar traidoramente, traicionar — obrar con deslealtad hacia Dios, un cónyuge o un aliado, violando la confianza o la fidelidad pactada. Se usa para referirse a la infidelidad de Israel (Jer 3:20; 5:11; Mal 2:10-11), a la traición conyugal (Éx 21:8; Mal 2:15) y a la deslealtad humana en general (1 S 14:33; Job 6:15). La duplicación enfática ''los traidores traicionan'' (בּוֹגְדִים בָּגָדוּ, Is 24:16; 33:1) es un recurso retórico característico de esta raíz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85159, 'spa', 'Persona traidora, traidor — participio sustantivado que designa a alguien caract', 'Persona traidora, traidor — participio sustantivado que designa a alguien caracterizado por una deslealtad habitual. Los Salmos y Proverbios los contraponen al justo: ''los traidores serán arrancados de la tierra'' (Pr 2:22), y ''miré a los desleales con repugnancia'' (Sal 119:158). La forma nominal estable en español ''traidor/traidores'' confirma que se trata de un sentido genuinamente sustantivo, no meramente verbal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85192, 'spa', 'vestidura, prenda', 'Cualquier prenda de vestir o cobertura corporal, sin distinción de calidad o estatus: desde la ropa inmunda de un leproso (Lv 13:47) hasta las vestiduras santas del sumo sacerdote (Éx 28:2). Aparece en todos los períodos del hebreo bíblico en contextos de vida cotidiana, consagración ritual (Lv 8:23-24), engaño (Gn 27:15; Gn 38:14) y actos simbólicos de duelo como rasgarse las vestiduras.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85259, 'spa', 'Nombre propio Bigvai', 'Nombre personal Bigvai, que identifica a un jefe de clan entre los exiliados que regresaron. Acompañó a Zorobabel desde Babilonia (Ezra 2:2; Neh 7:7), y sus descendientes formaron uno de los grupos familiares más numerosos (Ezra 2:14; Neh 7:19), con otro contingente bajo Esdras (Ezra 8:14). Un Bigvai también selló el pacto de Nehemías (Neh 10:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85262, 'spa', 'solo, por sí mismo', 'Con לְ y sufijos pronominales (לְבַדּוֹ, לְבַדִּי, etc.), בַּד expresa un estado solitario: ''solo, por sí mismo, únicamente''. Génesis 2:18 establece el peso existencial (''no es bueno que esté solo''), mientras que Zacarías 12:12-14 repite לְבַד para enfatizar un duelo aislado. El árabe وحده, el suajili peke yake y el coreano 홀로 confirman este significado adverbial-exclusivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85263, 'spa', 'aparte de, además de', 'La preposición compuesta מִלְּבַד (''desde-separación-de'') significa ''aparte de, además de, excepto''. Añade o excluye elementos de un recuento: ''además de mujeres y niños'' (Éx 12:37), ''aparte del holocausto continuo'' (Lv 9:17; 23:38). El árabe سِوى, el suajili mbali na y el español además de traducen esta función prepositiva excluyente-aditiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85266, 'spa', 'varas, pértigas', 'Como sustantivo concreto en plural (בַּדִּים), בַּד designa las varas o pértigas de transporte insertadas en los anillos para llevar el arca, el altar y la mesa del tabernáculo (Éx 25:13-15, 27-28). El español varas, el francés barres y el suajili mipiko confirman el significado instrumental. Estas varas encarnan físicamente la ''pieza separada y extendida'' en el núcleo de la raíz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85280, 'spa', 'parte, porción', 'En Éxodo 30:34, בַּד aparece en la receta de las especias como ''parte'' o ''porción igual'': ''especias aromáticas, cada una en parte igual (בַּד בְּבַד)''. La expresión denota porciones medidas y separadas de ingredientes. El español parte y el francés partie confirman la lectura partitiva, vinculándose con el árabe بِدّ (porción) que ancla la etimología de la raíz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85289, 'spa', 'miembros del cuerpo', 'Referido a los miembros o partes de un cuerpo, como en Job 18:13 donde la enfermedad devora ''los miembros de su cuerpo'' (בַּדֵּי עוֹרוֹ). La acepción extiende el significado de ''parte separada'' a los miembros anatómicos. El español partes y la doble aparición en Job confirman esta aplicación corporal de la raíz partitiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85300, 'spa', 'ramas, sarmientos', 'Ramas o sarmientos de una planta, especialmente de la vid: Ezequiel 17:6 describe ''sarmientos'' (בַּדִּים) que se extienden, y 19:14 menciona el fuego que consume las ramas. La acepción botánica es paralela a la corporal de ''miembro'': ambas son extensiones o partes separadas que crecen de un cuerpo principal. El español sarmientos capta con precisión este uso hortícola.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85305, 'spa', 'cerrojos, barrotes', 'Cerrojos o barrotes de una puerta o fortificación, como en Oseas 11:6 donde la espada ''consume sus cerrojos'' (בַּדָּיו) y Job 17:16 donde la esperanza desciende a los ''cerrojos del Seol''. El español cerrojos/barrotes confirma el significado estructural. Son piezas separadas y alargadas usadas para asegurar — otra manifestación concreta del núcleo partitivo-separativo de la raíz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85315, 'spa', 'Tela de lino blanco reservada para vestiduras sagradas', 'Tela de lino blanco reservada para vestiduras sagradas: el efod de Samuel (1 S 2:18), el atuendo de adoración de David (2 S 6:14), las vestiduras levíticas (Éx 28:42; Lv 16:4) y las luminosas vestiduras de figuras angélicas en Ezequiel 9:2 y Daniel 10:5; 12:6-7. En español ''lino'' confirma un sentido único de material concreto. El término marca santidad y pureza, elevándose del uso sacerdotal terrenal al celestial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85317, 'spa', 'Habladuría vana, mentiras', 'Habla vacía, jactancia ociosa o mentiras; concretamente, charlatanes o falsos adivinos. Isaías 16:6 y Jer 48:30 denuncian las fanfarronadas de Moab (בַּדָּיו). Job 11:3 lo usa para la palabrería que acalla a otros. En Isa 44:25 y Jer 50:36, designa a falsos profetas como ''mentirosos'' cuyas oráculos son vana pretensión. Cognados fenicios lo confirman.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85319, 'spa', 'Miembros del cuerpo', 'Miembros o extremidades del cuerpo, un sentido homónimo distinto que aparece únicamente en Job 41:12 (hebreo 41:4), donde Dios describe los poderosos miembros de Leviatán (בַּדָּיו). Este significado anatómico no tiene conexión semántica con ''habla vana'' y representa una raíz léxica separada. La evidencia multilingüe selecciona uniformemente vocabulario corporal: inglés ''his limbs'', español ''sus miembros''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85323, 'spa', 'Solo o aislado', 'Estar solo, aislado o solitario, ya sea por imposición, circunstancia o decisión propia. El leproso debe habitar «solo» fuera del campamento (Lv 13:46), el salmista se compara con un ave solitaria en un tejado (Sal 102:7), el rezagado queda separado del ejército en retirada (Is 14:31) y Efraín es un asno montés que sigue su propio camino (Os 8:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85324, 'spa', 'Solo, solitario', 'Solo, solitario. El estado de estar solo, solitario o apartado, abarcando un rango semántico desde la distinción honorable hasta el aislamiento penoso. Positivamente: Israel habita «solo» como pueblo escogido y separado para Dios (Nm 23:9; Dt 33:28), y el SEÑOR «solo» guió a Israel por el desierto (Dt 32:12). Negativamente: Jerusalén está «sola» como viuda en su desolación (Lm 1:1), y Jeremías se sentó «solo» bajo el peso de la palabra profética (Jr 15:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85329, 'spa', 'Estaño', 'Estaño como metal base (plumbum album), enumerado entre los metales de comercio y botín de guerra (Num 31:22; Ezek 22:18, 20; 27:12). En la imaginería del horno de Ezequiel, Israel queda reducida a estaño y escoria entre metales más nobles. Las traducciones al español usan consistentemente ''estaño'' para este sentido metalúrgico específico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85331, 'spa', 'Plomada', 'Peso de plomada o plomada, usado en la frase constructa ''la piedra de estaño'' (Zech 4:10). El metal denso sirve como contrapeso en la plomada del constructor. Español ''la de plomo'' refleja la función pesada y colgante. Símbolo de la medición exacta de Dios sobre la obra del templo de Zorobabel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85332, 'spa', 'Aleación o escoria', 'Aleación o escoria, la impureza base adherida a la plata tras la fundición. En Isaías 1:25, Dios promete fundir ''tu impureza'' de Jerusalén. Español ''tu impureza'' capta la metáfora moral-metalúrgica: el pecado como contaminante que debe quemarse antes de que la ciudad pueda llamarse justa nuevamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85334, 'spa', 'Hifil', 'Hifil: separar, apartar — el sentido causativo de separar, dividir o apartar activamente personas o cosas, ya sea para división física, consagración ritual o elección divina. Este sentido dominante (29 apariciones) comienza en la creación misma: Dios separando la luz de las tinieblas (Gn 1:4), las aguas de arriba de las de abajo (Gn 1:6-7), y el día de la noche (Gn 1:14, 18). Se extiende a la consagración de Israel: ''Yo os he apartado de los pueblos'' (Lv 20:26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85338, 'spa', 'Nifal', 'Nifal: ser separado, retirarse — el sentido pasivo/reflexivo de ser separado o separarse uno mismo, retirarse de un grupo o comunidad. Con 10 apariciones, esta forma describe tanto la exclusión ordenada como la voluntaria: ''Apartaos de esta congregación'' (Nm 16:21), los guerreros que ''se separaron'' para unirse a David en Siclag (1 Cr 12:9), y repetidamente en Esdras-Nehemías donde los exiliados retornados ''se separaron'' de los pueblos de la tierra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85356, 'spa', 'Hifil', 'Hifil: distinguir, diferenciar — el sentido Hifil de hacer una distinción cognitiva o judicial entre categorías, ''distinguir'' o ''diferenciar'', en lugar de separar físicamente. Solo 3 apariciones claras, todas en instrucción sacerdotal: Levítico 10:10, donde los hijos de Aarón deben ''distinguir entre lo santo y lo profano, entre lo inmundo y lo limpio''; Levítico 11:47 y Ezequiel 22:26.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85371, 'spa', 'Brecha, grieta o fisura estructural en un edificio — especialmente el templo de ', 'Brecha, grieta o fisura estructural en un edificio — especialmente el templo de Jerusalén — que requiere reparación profesional. Domina 2 Reyes 12:5-12 (paralelo en 2 Cr 24:4-12), donde Joás dirige la labor de sacerdotes y artesanos para reparar el deterioro del templo (בֶּדֶק הַבַּיִת). También se usa para el calafateo de barcos en Ezequiel 27:9, 27, donde los artesanos de Gebal reparan las juntas o filtraciones de las naves comerciales de Tiro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85377, 'spa', 'Vacío primordial', 'Vacío o nada que describe el caos, ya sea primordial (Génesis 1:2) o como resultado del juicio divino. La visión de Jeremías sobre Judá devastada invierte el lenguaje de la creación: «Miré la tierra, y he aquí que era תֹּהוּ וָבֹהוּ» (Jeremías 4:23). Isaías retrata a Edom medida con «el cordel de confusión y las piedras de vacío» (Isaías 34:11), convirtiendo los instrumentos de edificación en herramientas de destrucción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85381, 'spa', 'Apresurarse, actuar con prisa (Nifal) — el sentido de ser precipitado o actuar c', 'Apresurarse, actuar con prisa (Nifal) — el sentido de ser precipitado o actuar con premura, con cuatro apariciones, todas en la literatura sapiencial. Proverbios 28:22 advierte que el de ''ojo malo'' se apresura tras la riqueza; Eclesiastés previene contra ''apresurarse en el espíritu a enojarse'' (7:9) o dejar que el corazón ''se apresure a proferir palabra ante Dios'' (5:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85382, 'spa', 'Ser apresurado (Pual) — el sentido pasivo de ser apresurado u obtenido con prisa', 'Ser apresurado (Pual) — el sentido pasivo de ser apresurado u obtenido con prisa. En Est 8:14 los correos reales ''fueron apresurados'' por mandato urgente del rey; en Pr 20:21 una herencia ''adquirida apresuradamente'' no será bendecida al final.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85383, 'spa', 'Aterrorizarse, consternarse (Nifal) — el sentido reflexivo-pasivo de estar aterr', 'Aterrorizarse, consternarse (Nifal) — el sentido reflexivo-pasivo de estar aterrorizado, consternado o profundamente conmocionado. Los hermanos de José ''se turbaron ante su presencia'' (Gn 45:3); los valientes de Moab fueron presa del temblor (Éx 15:15); la adivina de Endor ''se aterró'' ante la aparición (1 S 28:21). Es el sentido dominante con veintidós de treinta y nueve apariciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85390, 'spa', 'Aterrorizar, alarmar (Piel) — el sentido causativo de terror', 'Aterrorizar, alarmar (Piel) — el sentido causativo de terror: aterrorizar, alarmar o espantar a otra persona. Los mensajeros de Senaquerib hablan para aterrorizar a los defensores de Jerusalén (2 Cr 32:18); los adversarios conspiran ''para aterorizarlos'' e impedir la reconstrucción del templo (Esd 4:4); los terrores de Dios ''se despliegan contra'' Job (Job 6:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85393, 'spa', 'Apresurar a alguien (Piel) — el sentido causativo de prisa', 'Apresurar a alguien (Piel) — el sentido causativo de prisa: apresurar o dar prisa a alguien. En 2 Cr 35:21 el faraón Necao dice a Josías que Dios le ordenó ''apresurarse'' en su campaña; en Est 2:9 el eunuco del rey ''se apresuró'' a proveer a Ester de cosméticos y asistentes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85411, 'spa', 'Hacer apresurar (Hifil) — el sentido causativo intensivo', 'Hacer apresurar (Hifil) — el sentido causativo intensivo: hacer que alguien se apresure o sacar a alguien con urgencia. En 2 Cr 26:20 los sacerdotes ''sacaron apresuradamente'' al rey leproso Uzías del templo; en Est 6:14 los eunucos del rey ''se apresuraron a traer'' a Amán al banquete.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85418, 'spa', 'Alarmar, aterrorizar o causar consternación (Pael e Hitpaal)', 'Alarmar, aterrorizar o causar consternación (Pael e Hitpaal). Describe el efecto psicológico abrumador de los sueños proféticos y las visiones divinas en Daniel. El sueño de Nabucodonosor del gran árbol ''lo alarmó'' (Dn 4:5, 19), y el espíritu de Daniel fue ''turbado'' por la visión de las cuatro bestias (Dn 7:15, 28). El encuentro de Belsasar con la mano divina escribiendo en la pared emplea esta misma raíz para retratar su terror paralizante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85419, 'spa', 'Apresuradamente, con prisa — el infinitivo Hitpael con preposición beth usado ad', 'Apresuradamente, con prisa — el infinitivo Hitpael con preposición beth usado adverbialmente. El vínculo semántico con la alarma se preserva: uno se apresura porque está agitado o alarmado. Arioc lleva a Daniel ''apresuradamente'' ante Nabucodonosor (Dn 2:25), los funcionarios corren al horno de fuego (Dn 3:24), y Darío se precipita al foso de los leones al amanecer (Dn 6:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85424, 'spa', 'Terror repentino', 'Terror súbito, espanto o ruina catastrófica que llega sin aviso. Forma parte del vocabulario de maldiciones del pacto en Levítico 26:16; aparece en el Salmo 78:33 donde Dios consume los años de Israel «en terror repentino»; y en Jeremías 15:8 describe el pánico infligido a la madre de guerreros. Isaías 65:23 lo emplea en negación: los bendecidos no engendrarán hijos para calamidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85425, 'spa', 'bestia, animal grande', 'Cualquier animal terrestre grande o cuadrúpedo, usado genéricamente para las bestias del campo o los animales como clase distinta de la humanidad, las aves, los peces y los reptiles. El alemán traduce esta acepción como ''Tier'' (animal) y el español como ''bestia/animal''. Prominente en oráculos de juicio donde la destrucción arrasa ''desde el hombre hasta la bestia'' (Éx 9:25; Jer 50:3; Sal 135:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85429, 'spa', 'ganado, res doméstica', 'Animales domésticos de rebaño — ganado, reses — mantenidos para el trabajo agrícola, la alimentación o el valor económico. Las construcciones posesivas (''tu bestia'', ''su bestia'') señalan propiedad y crianza. El alemán pasa consistentemente a ''Vieh'' (ganado) y el español a ''ganado'' en estos contextos. Central para la vida del pacto: el descanso sabático se extiende a tu בְּהֵמָה (Éx 20:10), y el justo cuida de su ganado (Pr 12:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85505, 'spa', 'Pulgar o dedo gordo del pie (parte del cuerpo) — El pulgar (cuando se empareja c', 'Pulgar o dedo gordo del pie (parte del cuerpo) — El pulgar (cuando se empareja con ''mano'') o el dedo gordo (cuando se empareja con ''pie''), refiriéndose siempre al dedo mayor de la respectiva extremidad. Casi todas las ocurrencias son rituales: la consagración de sacerdotes implica untar sangre sacrificial en el pulgar derecho y el dedo gordo del pie derecho (Éx 29:20; Lv 8:23-24), y la purificación de leprosos sigue el mismo patrón con sangre y aceite (Lv 14:14-28).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85509, 'spa', 'Mancha brillante o blanca en la piel examinada por el sacerdote conforme a las l', 'Mancha brillante o blanca en la piel examinada por el sacerdote conforme a las leyes levíticas de pureza para diagnosticar un posible tzaraat (Lv 13:2, 4, 19, 23-26, 28, 38-39). Se evaluaba su profundidad, el color del vello y si se había extendido. Un término técnico dermatológico-cultual exclusivo de Levítico 13-14, con las doce apariciones confinadas a estas regulaciones sacerdotales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85513, 'spa', 'venir, llegar (Qal)', 'Sentido Qal dominante: venir, llegar, alcanzar un destino — 2.413 ocurrencias que abarcan el movimiento general hacia un punto de referencia. Incluye llegadas narrativas (''y vino Abraham a Hebrón'', Gn 13:18), fórmulas proféticas (''vino palabra del SEÑOR a...'') y expectativas escatológicas (''vendrá el día del SEÑOR''). Multilingüísticamente uniforme: español vino/llegó, árabe جاء, suajili kuja.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85555, 'spa', 'traer, llevar (Hifil)', 'Causativo Hifil: traer, llevar, transportar o entregar a alguien o algo a un lugar — 62 ocurrencias. Isaac pide a Esaú que le ''traiga'' caza (Gn 27:4), los hermanos de José ''trajeron'' a Benjamín a Egipto (Gn 43:15) y Dios promete ''introducir'' a Israel en la tierra. Español trajo/trajeron, árabe أحضر, suajili leta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85569, 'spa', 'entrar, ir adentro (Qal)', 'Variante Qal con matiz específico de ''entrar'': ir dentro de un espacio cerrado, acotado o definido — 112 ocurrencias. Noé ''entró'' en el arca (Gn 7:7), Lot instó a los ángeles a ''entrar'' en su casa (Gn 19:3) e Israel recibe el mandato de ''entrar'' en la tierra. Se distingue del sentido 1 por la contención espacial explícita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85697, 'spa', 'ser traído (Hofal)', 'Pasivo Hofal: ser traído, ser introducido, ser conducido — solo 5 ocurrencias, la forma verbal más rara de este verbo. Los hermanos de José temen que ''son traídos'' a la casa del mayordomo (Gn 43:18), la plata ''fue traída'' al templo (2 R 12:9) y el libro de la ley ''fue traído'' al rey (2 R 22:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85784, 'spa', 'Tener en desprecio o menosprecio, tratando a alguien o algo como carente de valo', 'Tener en desprecio o menosprecio, tratando a alguien o algo como carente de valor. Predomina en Proverbios: los necios desprecian la sabiduría (Pr 1:7), un ladrón hambriento no es despreciado (Pr 6:30). Enfatiza la actitud subjetiva de desdén más que el acto formal de rechazo. Un sentido unificado de desprecio activo que aparece tanto en la literatura sapiencial como en el discurso profético.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85794, 'spa', 'Desprecio, desdén o rechazo desdeñoso dirigido a una persona o cosa considerada ', 'Desprecio, desdén o rechazo desdeñoso dirigido a una persona o cosa considerada indigna o vergonzosa. Judá teme convertirse en ''hazmerreír'' si sus tratos con Tamar se hacen públicos (Gn 38:23). Los discursos de Job están saturados de este término: los prósperos vierten desprecio sobre el que tropieza (Job 12:5), los nobles son tratados con desprecio (Job 12:21), y Job teme el escarnio público (Job 31:34). El salmista suplica liberación del desprecio y el oprobio (Sal 31:18; 119:22; 123:3-4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85800, 'spa', 'Nombre propio y tribal', 'Nombre personal (hijo de Nacor en Génesis 22:21; un gadita en 1 Crónicas 5:14) y nombre tribal de un grupo árabe mencionado junto a Dedán y Tema (Jeremías 25:23). La referencia tribal sitúa a Buz dentro de la red de pueblos del norte de Arabia, enlazando las genealogías ancestrales con el panorama geopolítico de la época de Jeremías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85805, 'spa', 'Confusión y desconcierto', 'Estar confuso, aturdido o desorientado. Faraón creerá que los israelitas «andan perdidos» en el desierto (Éxodo 14:3). Susa queda «sumida en desconcierto» ante el decreto de exterminar a los judíos (Ester 3:15). Los rebaños «vagan perplejos» por falta de pastos (Joel 1:18). El Nifal transmite una desorientación pasiva: confusión impuesta por circunstancias externas más que elegida voluntariamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85809, 'spa', 'Hitpael reflexivo', 'Hitpael reflexivo: revolcarse, agitarse, específicamente en sangre. Se encuentra en Ezequiel 16:6 y 16:22, donde Dios se dirige a Jerusalén infante como una expósita ''revolcándose en tu sangre'' -- imagen de movimiento convulsivo e indefenso. Este sentido se aparta enteramente del significado hostil de pisotear, centrándose en el movimiento reflejo agitado de un recién nacido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85810, 'spa', 'Qal', 'Qal: pisotear u hollar, expresando victoria militar decisiva o dominio. El SEÑOR pisotea a Asiria en sus montes (Is 14:25) y holla a los pueblos en su furor (Is 63:6); el salmista confía en que Dios le ayudará a ''pisotear a nuestros adversarios'' (Sal 44:5; 60:12; 108:13). En Proverbios 27:7, el alma saciada ''pisotea'' incluso el panal, extendiendo la imagen al rechazo despectivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85812, 'spa', 'Poel intensivo', 'Poel intensivo: pisotear completamente, enfatizando la totalidad y severidad de la devastación. En Jeremías 12:10, muchos pastores ''han pisoteado'' la viña de Dios; en Isaías 63:18, los adversarios ''han hollado'' el santuario. La conjugación intensiva señala que no es un acto aislado sino una destrucción sostenida y ruinosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85815, 'spa', 'Hofal pasivo', 'Hofal pasivo: ser pisoteado, la contraparte pasiva del pisoteo activo. Atestiguado una vez en Isaías 14:19, donde el rey caído de Babilonia es comparado con un cadáver ''pisoteado'' bajo los pies -- arrojado de su sepulcro como rama repugnante, hollado por los muertos. Imagen de degradación total.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85820, 'spa', 'Lino fino (biso)', 'Tela fina de lino blanco (biso), utilizada para vestiduras sacerdotales, la cortina del templo y atuendos reales. En 1 Crónicas 4:21 identifica a familias dedicadas al trabajo del biso como oficio hereditario. En 2 Crónicas 5:12 los cantores levitas están vestidos con ella, y Ester 8:15 describe a Mardoqueo con un manto real de bus. El francés fin lin y el español lino fino la traducen como ''lino fino'', confirmando la identidad textil.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85831, 'spa', 'Pozo, hoyo en el suelo — el sentido primario que abarca un pozo u hoyo en el sue', 'Pozo, hoyo en el suelo — el sentido primario que abarca un pozo u hoyo en el suelo, ya sea natural o excavado deliberadamente. Incluye fosos para atrapar animales o enemigos y, en textos poéticos y proféticos, el pozo metafórico del Seol o la sepultura: ''los que descienden al pozo'' (Sal 28:1, Is 14:15). Las 49 ocurrencias abarcan tanto el sentido concreto como el figurado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85836, 'spa', 'Cisterna, pozo para agua — cisterna o pozo excavado en la roca para almacenar ag', 'Cisterna, pozo para agua — cisterna o pozo excavado en la roca para almacenar agua de lluvia, tecnología vital de supervivencia en el Levante semiárido. Deuteronomio 6:11 enumera las cisternas entre las bendiciones de la Tierra Prometida, y Proverbios 5:15 empareja בּוֹר con בְּאֵר (pozo) como figura de la fidelidad conyugal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85849, 'spa', 'Prisión, calabozo — extensión metafórica poco frecuente donde ''pozo'' significa p', 'Prisión, calabozo — extensión metafórica poco frecuente donde ''pozo'' significa prisión o mazmorra, un lugar de confinamiento. En Génesis 41:14, José es sacado del בּוֹר (el calabozo de la prisión del faraón), y Éxodo 12:29 menciona al cautivo en el בּוֹר. Se distingue del pozo abierto o la cisterna de agua.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85860, 'spa', 'avergonzarse, sentir vergüenza', 'Sentido estativo Qal fundamental que abarca la experiencia de vergüenza, deshonra o humillación. El sujeto padece la vergüenza internamente, ya como juicio divino, exposición social o fracaso moral. Su amplitud es notable: va desde la vergüenza de naciones derrotadas (Is 37:27) hasta el arrepentimiento personal (Jer 31:19). El español «avergonzarse» conserva este carácter reflexivo e introspectivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85864, 'spa', 'causar vergüenza (Hifil)', 'Causativo Hifil: avergonzar, causar deshonra, infligir vergüenza a otro. Un agente activo impone la vergüenza sobre alguien. Los Salmos emplean este sentido frecuentemente en peticiones que piden a Dios avergonzar a los impíos (Sal 44:7; 119:31). El paso de experimentar vergüenza a provocarla marca una escalada semántica significativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85888, 'spa', 'secarse, marchitarse', 'Sentido único o casi único en Oseas 13:15 que significa secarse o marchitarse, aplicado a un manantial cuyas aguas se agotan. La evidencia multilingüe se divide: el español traduce «se secará». Puede reflejar una raíz homónima distinta o una extensión metafórica donde la vergüenza se asimila al marchitamiento de la vitalidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85896, 'spa', 'tardar, demorar (Piel)', 'Desarrollo Piel distintivo que significa tardar, demorar o ser lento en llegar. Es semánticamente distante de la vergüenza y probablemente surgió de la idea de vacilación prolongada. Las dos atestiguaciones —la demora de Moisés en el Sinaí (Éx 32:1) y la madre de Sísara preguntándose por qué tarda su carro (Jue 5:28)— involucran espera ansiosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85911, 'spa', 'Vergüenza pública', 'Vergüenza o deshonra experimentada como humillación pública o juicio divino. En el Salmo 89:45 el rey ungido es envuelto en vergüenza; Ezequiel 7:18 describe el oprobio cubriendo los rostros en el día de la ira; Abdías 1:10 anuncia la desgracia sobre Edom por su violencia fraternal; y Miqueas 7:10 anticipa al enemigo revestido de vergüenza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85913, 'spa', 'Bienes, posesiones o personas tomados por la fuerza, particularmente en conquist', 'Bienes, posesiones o personas tomados por la fuerza, particularmente en conquistas militares o incursiones. Frecuentemente emparejado con שָׁלָל (''despojo'') como cuasi-sinónimo en textos proféticos (Is 10:6; Ez 38:12-13). La expresión הָיָה לְבַז (''volverse despojo'') aparece en Nm 14:3 y Jer 49:32, aplicada tanto a ganado como a personas. En español ''despojo'', ''botín'' y ''presa'' captan la violenta realidad económica de la conquista antigua.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85927, 'spa', 'Despreciado, menospreciado — la condición pasiva o estativa de ser despreciado, ', 'Despreciado, menospreciado — la condición pasiva o estativa de ser despreciado, desdeñado o considerado sin valor por otros. El Mesías es ''despreciado y desechado entre los hombres'' (Is 53:3; Sal 22:6), el salmista justo es ''pequeño y despreciado'' (Sal 119:141), y la sabiduría del pobre ''es menospreciada'' (Ec 9:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85929, 'spa', 'Despreciar, tener en menosprecio — el sentido activo Qal de tratar algo o a algu', 'Despreciar, tener en menosprecio — el sentido activo Qal de tratar algo o a alguien como indigno, por debajo de toda consideración. Esaú despreció su primogenitura (Gn 25:34), Mical despreció a David por danzar (2 S 6:16), y Dios advierte que quienes lo desprecien serán tenidos en poco (1 S 2:30).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85945, 'spa', 'Despreciar (uso infinitivo) — un uso infinitivo o de propósito que aparece en Es', 'Despreciar (uso infinitivo) — un uso infinitivo o de propósito que aparece en Ester 1:17, donde la negativa de la reina llevará a otras mujeres ''a despreciar'' a sus maridos. Es funcionalmente idéntico al sentido 1, pero ocurre en una construcción infinitiva que señala consecuencia anticipada en lugar de acción completada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85962, 'spa', 'Bienes materiales — ganado, posesiones, objetos de valor — arrebatados a los ene', 'Bienes materiales — ganado, posesiones, objetos de valor — arrebatados a los enemigos vencidos tras la batalla o el saqueo. Usado del botín de Asa después de la derrota cusita (2 Cr 14:14), de la abstención deliberada de los judíos respecto al botín en Ester (9:10, 15-16), y de la visión de Daniel sobre un rey que distribuye despojos (11:24). La restricción de la palabra a textos tardíos sugiere que pudo haber entrado al hebreo por contacto con el arameo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85968, 'spa', 'Saquear, tomar como botín — el sentido activo principal', 'Saquear, tomar como botín — el sentido activo principal: saquear, desvalijar o llevarse posesiones como botín de guerra. Abarca toda la gama de formas verbales finitas: perfecto, imperfecto, imperativo, cohortativo e infinitivo. Domina las narraciones bélicas del Pentateuco (Nm 31:9, 32, 53; Dt 2:35; 3:7) y los relatos de la conquista (Jos 8:2; 11:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85978, 'spa', 'Saqueador, despojador — el participio activo funcionando como sustantivo agentiv', 'Saqueador, despojador — el participio activo funcionando como sustantivo agentivo: un saqueador o despojador, aquel cuya actividad característica es tomar botín. En Is 42:24 el profeta pregunta ''¿Quién entregó a Jacob a los saqueadores?''; en Jer 30:16 Dios promete que ''todos los que te despojan serán despojados''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85981, 'spa', 'Ser saqueado, ser despojado — el sentido pasivo (Nifal y construcciones afines)', 'Ser saqueado, ser despojado — el sentido pasivo (Nifal y construcciones afines): ser saqueado, desvalijado o despojado. En Is 24:3 la duplicación ''la tierra será enteramente saqueada'' intensifica la devastación mediante la construcción de infinitivo absoluto. Jer 50:37 profetiza que los tesoros de Babilonia ''serán saqueados'', y Am 3:11 advierte que las fortalezas de Samaria ''serán despojadas''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (85997, 'spa', 'Despojado (estado resultativo) — una aparición en Is 42', 'Despojado (estado resultativo) — una aparición en Is 42:22 donde la forma ''saqueado'' describe el estado de un pueblo completamente despojado: ''pueblo saqueado y despojado''. Las traducciones apuntan a una lectura estativa o resultativa: no el acto de ser saqueado, sino la condición de haber sido saqueado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86003, 'spa', 'Topónimo militar', 'Ciudad en territorio israelita mencionada como campo de batalla y punto de reunión. Judá y Simeón combatieron a los cananeos y ferezeos «en Bezec» y capturaron a Adoni-bezec (Jueces 1:4-5). Saúl contó las tropas «en Bezec» antes de marchar a rescatar Jabés de Galaad (1 Samuel 11:8). La preposición locativa constante en las traducciones confirma su función de topónimo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86007, 'spa', 'Joven, mozo — un hombre joven en edad militar o casadera, el uso sustantival est', 'Joven, mozo — un hombre joven en edad militar o casadera, el uso sustantival estándar. La pareja בָּחוּר וּבְתוּלָה (''joven y doncella'') se repite en la poesía y la profecía (Dt 32:25; 2 Cr 36:17; Sal 148:12). Saúl es descrito como un בָּחוּר en su plenitud (1 S 9:2); Proverbios celebra la fuerza de los jóvenes (Pr 20:29), y los textos proféticos lamentan la pérdida de la juventud de una nación bajo el juicio (Jer 6:11; Lm 1:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86025, 'spa', 'Escogido, elegido — el participio pasivo que conserva su fuerza verbal de בחר (''', 'Escogido, elegido — el participio pasivo que conserva su fuerza verbal de בחר (''elegir''): un escogido, un elegido. En el Sal 89:19 Dios declara ''He exaltado a un escogido (בָּחוּר) de entre el pueblo'', y Jer 50:44 pregunta ''¿Quién es el escogido que yo designaré?'' Este sentido raro revela la raíz etimológica que subyace al sustantivo común.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86033, 'spa', 'Persona o pueblo seleccionado por Dios para una relación de pacto, servicio o li', 'Persona o pueblo seleccionado por Dios para una relación de pacto, servicio o liberación. De uso exclusivamente teológico, este término designa al Siervo del SEÑOR (Is 42:1; 45:4), al remanente fiel (Is 65:9, 15, 22) e Israel colectivamente como pueblo escogido de Dios (Sal 105:6, 43; 106:5, 23; 1 Cr 16:13). David es el escogido de Dios en el Salmo 89:3. La palabra implica no una selección arbitraria sino un acto deliberado y pactual de elección divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86044, 'spa', 'Prueba divina de personas', 'Prueba divina de personas: Dios como sujeto que examina corazones, mentes y carácter interior para demostrar fidelidad o exponer falsedad. Es el sentido dominante (16 apariciones). Dios prueba al justo (Sal 11:5), escudriña el corazón y prueba la mente (Jer 11:20; 17:10; 20:12). La metáfora metalúrgica del refinamiento del oro recorre este uso (Job 23:10; Zac 13:9; Mal 3:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86046, 'spa', 'Súplica imperativa de prueba', 'Súplica imperativa de prueba: el salmista invitando el escrutinio de Dios como declaración de inocencia. ''Examíname, oh SEÑOR, y pruébame; aquilata mi corazón y mi mente'' (Sal 26:2; cf. 139:23). Semánticamente relacionado con el sentido 1, pero retóricamente distinto por la iniciativa humana y la vulnerabilidad de someterse al examen divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86049, 'spa', 'Ser probado, ser examinado (pasivo Nifal/Pual)', 'Ser probado, ser examinado (pasivo Nifal/Pual): someterse a examen o prueba. El Nifal y Pual aparecen en la prueba que José impone a sus hermanos: ''en esto seréis probados'' (Gn 42:15-16), y en la súplica de Job de que ''sea probado'' hasta el final (Job 34:36). Ezequiel 21:13 plantea la prueba como verificación escatológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86050, 'spa', 'Prueba humana de Dios', 'Prueba humana de Dios: la inversión del sentido 1, donde los humanos son los agentes que prueban, desafían o ponen a prueba la paciencia y las promesas de Dios. El Salmo 95:9 recuerda a Israel en el desierto: ''vuestros padres me probaron''. Malaquías 3:10 es la notable excepción donde Dios mismo invita a ser probado: ''Probadme en esto, dice el SEÑOR de los ejércitos''. La connotación va desde la provocación pecaminosa hasta la prueba divinamente autorizada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86067, 'spa', 'Proceso o medio de probar', 'Proceso o medio de probar: el infinitivo constructo Qal que describe el acto de ensayar, especialmente en la comparación metalúrgica. Zacarías 13:9 dice que Dios los refinará ''como se prueba el oro''. El infinitivo abstrae agente y paciente para enfocarse en el procedimiento mismo: el arte del refinador como imagen de la purificación divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86068, 'spa', 'Torre defensiva u ofensiva', 'Torre con función de vigilancia (defensiva) o de asedio (ofensiva). Isaías 32:14 alude a la «atalaya» como punto de referencia que será abandonado. Isaías 23:13 posiblemente describe torres de asedio levantadas contra Tiro, aunque el texto es problemático. El término aparece con variantes ketiv/qere, lo que refleja incertidumbre escribal sobre la forma exacta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86071, 'spa', 'elegir, seleccionar (Qal)', 'Sentido Qal activo central de elegir o seleccionar deliberadamente, con diferencia el uso dominante con 145 ocurrencias. Abarca tanto la elección divina (Dios elige a Abraham, Israel, los levitas, Jerusalén, la línea davídica: Dt 4:37; 7:6-7; Neh 9:7) como la elección humana (Josué recibe la orden de «escoger hombres» en Éx 17:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86075, 'spa', 'escogido, electo (participio)', 'Participio pasivo Qal usado sustantivamente: «escogido(s), electo(s), selecto(s)». Aparece 16 veces como virtual título o marca de estatus: guerreros de élite (Jue 20:15-16, 600 benjaminitas escogidos), oficiales selectos del faraón (Éx 14:7) e Israel como pueblo electo de Dios (1 S 24:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86082, 'spa', 'ser escogido (Nifal)', 'Forma Nifal pasiva o reflexiva: «ser escogido, ser preferido, ser más deseable». Se encuentra 7 veces, concentradas en la literatura sapiencial de Proverbios, donde se ordenan cualidades abstractas: «escogido es mi fruto más que el oro» (Pr 8:19), «la lengua del justo es plata escogida» (Pr 10:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86126, 'spa', 'variante textual (Ecl 9:4)', 'Ocurrencia única en Eclesiastés 9:4 que involucra una variante textual ketiv/qere. El ketiv lee «es unido» (יְחֻבַּר) mientras el qere lee «es escogido» (יִבָּחֵר), generando incertidumbre traductológica. El sentido del pasaje —que un perro vivo es mejor que un león muerto— se mantiene en ambos casos, pero el mecanismo textual distingue esta ocurrencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86130, 'spa', 'selecto, excelente (adjetival)', 'Ocurrencia única en Cantares 5:15 donde בָּחוּר se emplea adjetivalmente para describir la apariencia del amado como «selecto como los cedros del Líbano». La palabra funciona aquí como adjetivo cualitativo que significa «excelente, de lo mejor» en vez de referirse a un acto de selección o un estatus de elección.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86137, 'spa', 'Juventud, mocedad', 'El estado o periodo de ser joven. Josué es descrito como ayudante de Moisés «desde su juventud» (Números 11:28), resaltando un largo servicio fiel iniciado tempranamente. Qohélet se dirige al joven: «Alégrate en tu juventud» (Eclesiastés 11:9) y «Acuérdate de tu Creador en los días de tu juventud» (Eclesiastés 12:1), instando al gozo templado por la responsabilidad durante los años formativos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86138, 'spa', 'Aldea benjaminita', 'Nombre propio de lugar, Bajurim (בַּחֻרִים, posiblemente ''aldea de los jóvenes''), asentamiento benjaminita al este de Jerusalén, cerca del monte de los Olivos, sobre el camino a Jericó. Funciona como marcador geográfico recurrente en los relatos davídicos: 2 Samuel 3:16 registra a Paltiel siguiendo a Mical llorando ''hasta Bajurim''; 2 Samuel 16:5 presenta a Simei maldiciendo a David desde allí durante la crisis de Absalón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86139, 'spa', 'Habla precipitada', 'Hablar de forma temeraria, irreflexiva o impulsiva, profiriendo palabras sin la debida deliberación. En Proverbios 12:18 el que habla precipitadamente se contrasta con el habla sabia; en Levítico 5:4 describe jurar un voto temerario con los labios; y el Salmo 106:33 registra cómo Moisés habló precipitadamente cuando su espíritu fue provocado en Meribá.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86140, 'spa', 'confiar en, apoyarse en', 'Sentido activo dominante: depositar confianza, seguridad o dependencia en alguien o algo. Abrumadoramente dirigido hacia Dios en los Salmos (Sal 28:7, «en él confié y fui socorrido»), se extiende también a alianzas humanas y fortificaciones (Dt 28:52; 2 R 18:19). Las glosas multilingües lo traducen consistentemente con verbos de confianza dirigida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86148, 'spa', 'sentirse seguro, estar tranquilo', 'Sentido estativo-intransitivo: sentirse seguro, estar a salvo o vivir en confianza despreocupada, sin un objeto directo de confianza. El ejemplo clásico es la gente de Lais viviendo «seguros y desprevenidos» (Jue 18:7, 10, 27). Job 40:23 lo aplica al hipopótamo sintiéndose seguro aunque el Jordán se desborde. El contexto determina si la seguridad es legítima o imprudente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86170, 'spa', 'hacer confiar (Hifil)', 'Causativo Hifil: hacer que alguien confíe o infundir seguridad en otro. Esta forma relativamente rara (5 ocurrencias) tiene gran peso teológico. El Salmo 22:9 recuerda que Dios hizo confiar al salmista desde el vientre materno, mientras que Jeremías condena a los falsos profetas que «hicieron confiar a Israel en la mentira» (Jer 28:15; 29:31).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86209, 'spa', 'Seguridad o confianza protectora, que funciona casi exclusivamente como modifica', 'Seguridad o confianza protectora, que funciona casi exclusivamente como modificador adverbial de verbos de existencia asentada. La colocación yashav lavetach (''habitar con seguridad'') se repite en contextos legales (Lv 25:18-19), proféticos (Jer 32:37; Ez 34:25) y sapienciales (Pr 3:29). Ezequiel 38:8, 11 la extienden a la paz escatológica. Las glosas multilingües convergen en el sentido adverbial unitario: ''con seguridad'', ''en sûreté'', ''in Sicherheit''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86219, 'spa', 'Confianza, seguridad', 'Confianza o seguridad depositada en una persona o un plan. El comandante asirio ridiculiza la confianza de Judá: «¿Qué confianza es esta en la que confías?» (2 Reyes 18:19; Isaías 36:4). Qohélet emplea el término en un proverbio que prefiere la vida con esperanza a la muerte sin ella (Eclesiastés 9:4). La palabra se centra en el estado psicológico y espiritual de la confianza, que puede estar bien o mal fundamentada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86222, 'spa', 'Cesar, detenerse', 'La conjugación intransitiva Pe''al (equivalente al Qal hebreo), que significa detenerse por sí solo o como resultado de una acción previa. Ambas ocurrencias aparecen en Ezra 4:24, en perfecto y participio, describiendo la obra del templo que había cesado. Español ''cesó/cesada'' capta la cualidad estativa y resultativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86223, 'spa', 'Hacer cesar (causativo)', 'La conjugación causativa Pa''el (equivalente al Piel hebreo), que significa forzar la detención de una actividad por autoridad o decreto externo. Las cuatro ocurrencias involucran a opositores políticos que obligan al cese de la reconstrucción del templo (Ezra 4:21, 23; 5:5; 6:8). Español ''hicieron cesar'' marca consistentemente al agente que impone la paralización.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86228, 'spa', 'Desde el vientre, desde el nacimiento — extensión idiomática que significa ''desd', 'Desde el vientre, desde el nacimiento — extensión idiomática que significa ''desde el nacimiento'' o ''desde el mismo origen'', usando la frase preposicional מִבֶּטֶן (''desde el vientre''). Sansón fue consagrado como nazareo ''desde el vientre'' (Jue 16:17); Job lamenta no haber muerto ''desde el vientre'' (Job 3:11) y reflexiona que salió desnudo ''del vientre de mi madre'' (Job 1:21). Este sentido pasa de la anatomía a la ontología: marca algo como congénito o predestinado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86229, 'spa', 'Seno materno, lugar de gestación — el útero como lugar donde el niño es llevado ', 'Seno materno, lugar de gestación — el útero como lugar donde el niño es llevado y formado antes de nacer. Es el sentido en las narrativas patriarcales: los gemelos de Rebeca luchando en su seno (Gn 25:23-24), la esterilidad de Raquel enmarcada como Dios reteniendo ''el fruto del vientre'' (Gn 30:2). Deuteronomio promete bendición sobre ''el fruto de tu vientre'' (Dt 7:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86231, 'spa', 'Vientre, abdomen — la parte blanda y media del cuerpo, ya sea de humanos o anima', 'Vientre, abdomen — la parte blanda y media del cuerpo, ya sea de humanos o animales. Se usa para el área del estómago en contextos de violencia (la espada de Ehud hundiéndose en el vientre de Eglón, Jue 3:21-22), de prueba ritual (las aguas amargas que hinchan el vientre, Nm 5:21-22), de alimentación y hambre (Pr 13:25, Ez 3:3), y metafóricamente como sede de la pasión interior o la avaricia (Job 20:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86262, 'spa', 'Cuerpo, ser físico — una única ocurrencia en Sal 31', 'Cuerpo, ser físico — una única ocurrencia en Sal 31:9 donde la angustia del salmista afecta ''mi vientre'' (בִּטְנִי), usado en paralelo con el ojo y el alma que se consumen de dolor. Aquí בֶּטֶן parece denotar el cuerpo entero o la constitución física más que específicamente el abdomen o el útero, reflejando la dificultad de los traductores ante un término que oscila entre el abdomen localizado y la totalidad corporal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86270, 'spa', 'Partícula discursiva de súplica cortés, equivalente a ''por favor'' o ''te ruego'', ', 'Partícula discursiva de súplica cortés, equivalente a ''por favor'' o ''te ruego'', usada al dirigirse a un superior (Gn 43:20; 44:18) o a Dios (Ex 4:10, 13). No posee significado independiente más allá de marcar deferencia y humildad. Una función pragmática única de apelación respetuosa que suaviza la petición del hablante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86273, 'spa', 'entender, percibir (Qal)', 'Sentido Qal activo fundamental: captar mentalmente, comprender o percibir un hecho o situación. Deuteronomio 32:29 («si fueran sabios y entendieran») y 1 Samuel 3:8 («Elí percibió que el Señor llamaba») muestran la comprensión cognitiva. Se trata de la aprehensión intelectual directa, la expresión más básica de esta raíz verbal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86274, 'spa', 'hacer entender, enseñar (Hifil)', 'Hifil en su fuerza causativa: hacer que alguien entienda, instruir o enseñar. 2 Crónicas 35:3 («enseñad a todo Israel»), Nehemías 8:7-9 («los levitas ayudaron al pueblo a entender la Ley») y Esdras 8:16 («hombres de entendimiento») muestran contextos pedagógicos claros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86276, 'spa', 'prudente, entendido (Nifal)', 'Formas participiales Nifal que funcionan como adjetivos para describir a una persona discerniente o prudente. Génesis 41:33 («busca un hombre entendido y sabio»), Deuteronomio 1:13 («hombres sabios y entendidos») y 1 Samuel 16:18 («hombre de entendimiento») ilustran el uso atributivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86279, 'spa', 'considerar, reflexionar (Hitpael)', 'Hitpael reflexivo-intensivo: considerar detenidamente, reflexionar o ponderar con profundidad. 1 Reyes 3:21 («cuando miré con atención»), Job 11:11 («ve la iniquidad, ¿no la considerará?») y Salmo 73:17 («hasta que entré en el santuario y comprendí») muestran un empeño mental deliberado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86281, 'spa', 'entender (infinitivo Qal/Hifil)', 'Uso infinitivo que expresa el concepto o propósito del entendimiento de forma abstracta. 1 Reyes 3:9 («para discernir entre el bien y el mal»), Proverbios 1:2 («para conocer sabiduría e instrucción, para entender palabras de inteligencia») muestran nominalizaciones o cláusulas de propósito. Es el entendimiento como meta u objeto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86282, 'spa', 'poseer entendimiento (Hifil)', 'Hifil en su sentido interno o estativo: poseer entendimiento, ser alguien dotado de perspicacia o inteligencia. 1 Reyes 3:11 («pediste entendimiento»), 1 Crónicas 15:22 («Quenanías era hábil en el entendimiento») y pasajes de Proverbios sobre sabios y necios ilustran este uso casi adjetival.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86286, 'spa', 'prestar atención, observar (Qal)', 'Subsentido Qal que enfatiza la atención o la observación más que la captación intelectual: «prestar atención», «fijarse», «observar». Deuteronomio 32:7 («considera los días antiguos»), Job 18:2 («¿hasta cuándo consideraréis las palabras?») y Proverbios 7:7 («observé entre los simples») muestran el enfoque perceptivo o atencional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86305, 'spa', 'obrar con prudencia', 'Ocurrencia única en 2 Crónicas 11:23 donde el contexto sugiere actuar sabia o prudentemente, quizá distribuyendo hijos de forma estratégica. El matiz semántico se inclina hacia la sabiduría práctica o la acción sagaz, más que hacia la comprensión intelectual. La evidencia multilingüe es escasa y requiere mayor refinamiento contextual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86342, 'spa', 'cuidar, proteger', 'Deuteronomio 32:10 presenta un posible sentido de cuidar o guardar: «lo rodeó, lo cuidó». El español «lo cuidó» y el alemán «er sorgte für ihn» sugieren un acto protector o nutriente distinto de la comprensión cognitiva. Puede representar una extensión semántica de percibir/atender hacia cuidar activamente, o bien un homónimo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86392, 'spa', 'entre, en medio de', 'Preposición que indica el intervalo o espacio que separa a dos o más referentes, ya sea espacial (Gn 15:17, «entre los trozos»), relacional (Gn 26:28, «entre nosotros»), temporal o conceptual (Gn 1:4, «entre la luz y las tinieblas»). Los cognados árabe بَيْن y arameo בֵּין confirman la función pansemítica de esta partícula. Los sufijos pronominales y las formas compuestas como מִבֵּין amplían su alcance a lo largo de casi todos los registros bíblicos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86415, 'spa', 'Entre, en medio de', 'Preposición «entre» o «en medio de» en las secciones arameas de Daniel. Describe la posición del oso «de un lado» (Daniel 7:5), el cuerno pequeño que surge «entre ellos» (Daniel 7:8, con variantes ketiv/qeré) y relaciones espaciales dentro de las visiones. Las glosas multilingües muestran cierta incertidumbre (corchetes en francés y alemán), reflejando las complejidades textuales del arameo de Daniel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86416, 'spa', 'Entendimiento, discernimiento o perspicacia como facultad cognitiva y moral, que', 'Entendimiento, discernimiento o perspicacia como facultad cognitiva y moral, que abarca el acto de comprender (Dn 9:22; Is 33:19), la capacidad innata de percibir distinciones (Job 20:3; 39:26; Pr 3:5), el objeto preciado de la búsqueda intelectual (Pr 4:5, 7; 16:16; Job 28:12, 20) y su personificación junto a la Sabiduría (Pr 7:4; 8:14). Las glosas multilingües convergen: ''entendimiento'', ''intelligence'', ''Verstand''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86431, 'spa', 'Huevo(s)', 'Huevos de aves o reptiles, siempre en plural. Abarca huevos literales en un nido bajo la ley mosaica (Deut 22:6), huevos de avestruz abandonados en el suelo (Job 39:14), y huevos en imágenes proféticas: recoger riqueza de naciones como huevos desprotegidos (Isa 10:14), y malvados incubando huevos de víbora que engendran muerte (Isa 59:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86437, 'spa', 'Ciudadela o fortaleza real fortificada, usada especialmente para la acrópolis pe', 'Ciudadela o fortaleza real fortificada, usada especialmente para la acrópolis persa en Susa: ''Susa la ciudadela'' (Neh 1:1; Est 1:2). Este es el sentido dominante, apareciendo en Ester, Nehemías y Daniel para designar el recinto real defendido dentro de una ciudad más grande. La distinción respecto a la ciudad circundante es clave en el uso del término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86438, 'spa', 'El complejo del templo en Jerusalén concebido como un recinto palaciego', 'El complejo del templo en Jerusalén concebido como un recinto palaciego. David le dice a Salomón: ''el palacio no es para hombre, sino para el SEÑOR Dios'' (1 Cr 29:1), y ora para que Salomón construya ''el palacio para el cual he hecho provisión'' (1 Cr 29:19). Aquí la palabra eleva el templo más allá de un simple santuario a una residencia real de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86441, 'spa', 'Entre, en medio de', 'Variante femenina de «entre», posiblemente con el sentido de «en medio de» o «en la encrucijada de». La evidencia es escasa y textualmente incierta: la Sabiduría se sitúa «entre» los caminos (Proverbios 8:2, según LXX, Targum y Vulgata); las raíces se extienden «entre» las piedras (Job 8:17); las cámaras del templo tienen espacio «entre» ellas (Ezequiel 41:9). Las traducciones modernas suelen verter como «encrucijada» o «casa de».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86442, 'spa', 'casa, vivienda, edificio', 'Sentido dominante: estructura física empleada como residencia, refugio, almacén, cárcel o lugar de reunión — más de 2.000 de unas 2.050 ocurrencias. Abarca casas (Gn 19:2-4), palacios (2 S 5:11), el templo como ''casa de Yahvé'' (1 R 6:1) y todas las flexiones preposicionales. La forma constructa bet- en ''casa de X'' es tan productiva que raya en la gramaticalización.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86468, 'spa', 'adentro, interior', 'Sentido espacial-direccional que significa ''adentro, interior, hacia dentro'' — unas 21 ocurrencias donde בַּיִת ha perdido su referencia arquitectónica y funciona como adverbio locativo o direccional. En Gn 6:14 se ordena a Noé calafatear el arca ''por dentro'' (mib-bayit); en Éx 25:11 el arca del pacto se recubre de oro ''por dentro''. Español por dentro/desde dentro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86474, 'spa', 'familia, linaje, dinastía', 'Extensión metonímica del edificio a sus habitantes: familia, linaje o dinastía real — unas 15 ocurrencias con este significado claramente en primer plano. ''Casa de David'' como designación dinástica (Sal 115:10, 12; 135:19), ''casa de Aarón'' como linaje sacerdotal y ''casa de Jacob/Israel'' como familia nacional ilustran este uso. Español casa de, linaje de.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86518, 'spa', 'templo, edificio oficial', 'Ocurrencia singular en Neh 2:8 donde בַּיִת designa específicamente el templo o un edificio oficial en el contexto de permisos de construcción. Nehemías solicita madera para ''la puerta de la ciudadela junto a la casa'' — traducido como ''templo'' en español y en inglés, mientras el francés conserva el genérico maison. Uso institucional especializado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86528, 'spa', 'Un edificio empleado como vivienda, palacio o templo', 'Un edificio empleado como vivienda, palacio o templo. En Esdras, beth elaha (''casa de Dios'') predomina con 28 de 44 usos ligados a la reconstrucción del templo de Jerusalén (Esd 5:2-3; 6:7). En Daniel designa el palacio real babilónico (Dn 4:4) y casas particulares (Dn 2:17). Las glosas multilingües reflejan uniformemente el sentido arquitectónico concreto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86542, 'spa', 'Bet-Avén (topónimo)', 'Nombre propio de un lugar al este de Betel que también funciona como epíteto profético. En Josué 7:2 y 18:12 marca un límite geográfico genuino cerca de Hai; en 1 Samuel 13:5 y 14:23 ubica campamentos filisteos. Pero en Oseas se transforma en un sobrenombre despectivo para Betel, condenando su culto idolátrico mediante un juego de palabras entre ''iniquidad'' y ''Dios''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86545, 'spa', 'Betel (ciudad) — el topónimo Betel (''casa de Dios''), que identifica la antigua c', 'Betel (ciudad) — el topónimo Betel (''casa de Dios''), que identifica la antigua ciudad en la serranía de Efraín donde Jacob vio la escalera celestial y consagró una estela (Gn 28:10-19; 35:1-15), donde se albergó el arca durante los jueces (Jue 20:26-28), y donde Jeroboam I erigió un becerro de oro, convirtiéndola en centro de culto condenado (1 R 12:28-33; Am 3:14; Os 10:15). Todas las lenguas de destino conservan el nombre propio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86577, 'spa', 'Topónimo transjordano', 'Nombre propio de una ciudad al este del Jordán cerca del mar Muerto, que significa «casa de los páramos». Marca el último campamento de Israel antes de cruzar el Jordán (Nm 33:49), aparece en las descripciones fronterizas del antiguo territorio de Sijón (Jos 12:3), fue asignada a Rubén (Jos 13:20) y figura entre las ciudades del flanco expuesto de Moab en Ezequiel 25:9.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86579, 'spa', 'Gentilicio de Belén', 'Adjetivo gentilicio que significa «de Belén», usado para identificar a personas por su ciudad de origen. Isaí es presentado como «el betlemita» en 1 Samuel 16:1, 18; David es reconocido como «hijo del betlemita» en 1 Samuel 17:58; y el guerrero Eljanán lleva la misma designación en 2 Samuel 21:19.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86583, 'spa', 'Ciudad fronteriza', 'Ciudad en la frontera entre Judá y Benjamín, nombrada por su ubicación en o cerca de la Arabá (el valle del Rift). El límite de Judá pasa «a Bet-Arabá» (Josué 15:6), la ciudad figura entre los asentamientos de Judá en el desierto (Josué 15:61) y aparece en el territorio de Benjamín (Josué 18:22). La evidencia multilingüe conserva el nombre con ligeras variaciones (Bet-Arabá, Beyth-ha-Aravah), mostrando adaptaciones de transliteración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86588, 'spa', 'Ciudad fronteriza', 'Ciudad en la frontera entre Judá y Benjamín, identificada con la actual Ain Hajla. Las descripciones de límites señalan que la frontera iba ''hasta Bet-hoglá'' (Josué 15:6; 18:19), y la ciudad fue asignada a Benjamín (Josué 18:21). El nombre, que significa ''casa de la perdiz'', se transliterar de forma consistente en las lenguas europeas, reflejando su condición de topónimo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86589, 'spa', 'Nombre propio Bet-horón (בֵּית חוֹרֹן, ''casa de la cavidad''), que designa ciudad', 'Nombre propio Bet-horón (בֵּית חוֹרֹן, ''casa de la cavidad''), que designa ciudades gemelas -- Alta y Baja -- sobre un paso montañoso estratégico en Efraín. El paso aparece en la gran victoria de Josué sobre la coalición amorrea (Jos 10:10-11), los proyectos de fortificación de Salomón (1 R 9:17; 2 Cr 8:5) y la asignación a los levitas coatitas (Jos 21:22). Construidas por Seera, hija de Efraín (1 Cr 7:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86594, 'spa', 'El topónimo Beth Lechem (''casa del pan''), que designa principalmente la ciudad j', 'El topónimo Beth Lechem (''casa del pan''), que designa principalmente la ciudad judía asociada con la sepultura de Raquel (Gn 35:19), la narrativa del levita y su concubina (Jue 19), los campos de Rut (Rt 1-4), los orígenes de David (1 S 16-17) y la expectativa mesiánica de Miqueas 5:1. También se la llama Efrata (Rt 4:11; Mi 5:1). Un segundo Belén en Zabulón aparece en Josué 19:15.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86613, 'spa', 'Ciudad cananea en Neftalí', 'Ciudad fortificada cananea en Neftalí que Israel no logró conquistar plenamente. Incluida en la herencia de Neftalí (Josué 19:38), Jueces registra que ''Neftalí no expulsó a los habitantes de Bet-anat'', quienes fueron sometidos a trabajos forzados (Jueces 1:33). El nombre ''templo de Anat'' indica un centro religioso cananeo cuya persistencia ilustra el control israelita incompleto en el norte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86614, 'spa', 'Sitio de la matanza', 'Lugar donde Jehú mató a cuarenta y dos parientes del rey Ocozías. El texto lo llama ''Bet-eqed de los pastores'' (2 Reyes 10:12) y ''el pozo de Bet-eqed'' (v. 14). El nombre sugiere una instalación pastoril, y el sitio fue escenario de una brutal masacre durante la campaña de Jehú para erradicar la casa de Acab.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86615, 'spa', 'Ciudad del Neguev', 'Ciudad en la región meridional de Judá, incluida entre los asentamientos del Neguev (Josué 15:27) y repoblada después del exilio babilónico (Nehemías 11:26). El nombre ''casa de escape'' podría conmemorar una liberación histórica. Las traducciones al español y al inglés lo rinden de manera consistente, confirmando su estatus como topónimo reconocido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86616, 'spa', 'Lugar en Moab', 'Nombre propio de una localidad en Moab al este del Jordán, que significa ''casa de Peor.'' Moisés pronunció sus discursos finales a Israel en el valle frente a Bet-peor (Dt 3:29; 4:46), fue sepultado en un valle de esa tierra (Dt 34:6), y el sitio fue adjudicado a Rubén (Jos 13:20). Designa un único emplazamiento geográfico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86618, 'spa', 'Ciudad fortificada judeana', 'Nombre propio de una ciudad fortificada en la serranía de Judá, que significa ''casa de roca.'' Incluida entre las ciudades de Judá (Jos 15:58), fortificada por Roboam (2 Cr 11:7) y representada en la reconstrucción de los muros bajo Nehemías (Neh 3:16). En 1 Crónicas 2:45 funciona como nombre personal en el linaje calebita, probablemente como ancestro epónimo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86619, 'spa', 'Ciudad aramea del norte', 'Ciudad o distrito arameo del norte asociado con Dan y las vías de acceso a Hamat. Lais (luego Dan) estaba ''en el valle que pertenece a Bet-rejob'' (Jueces 18:28). Cuando Amón contrató mercenarios arameos, estos vinieron de ''Aram Bet-rejob'' (2 Samuel 10:6). Su conexión con Rejob sugiere que era tanto una ciudad como una designación regional en el extremo norte, fuera del control israelita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86621, 'spa', 'Bet-Seán (topónimo)', 'Bet-Seán (también Bet-Shan) — nombre propio de la ciudad fortificada situada en la confluencia estratégica de los valles de Jezreel y del Jordán, en el territorio de Manasés. Aunque fue asignada a esta tribu, la población cananea no pudo ser expulsada (Jos 17:11, 16; Jue 1:27). Es recordada sobre todo como el lugar donde los filisteos exhibieron los cadáveres de Saúl y sus hijos tras la batalla de Guilboa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86628, 'spa', 'Nombre de lugar que significa ''casa del sol'', designando principalmente la ciuda', 'Nombre de lugar que significa ''casa del sol'', designando principalmente la ciudad levítica en el suroeste de Judá, cerca de la frontera filistea. Conocida como el destino del Arca al ser devuelta (1 S 6:9-20) y el sitio de la derrota de Amasías ante Joás (2 R 14:11-13; 2 Cr 25:21-23). También designa ciudades en Neftalí (Jos 19:38; Jue 1:33, donde los cananeos no fueron expulsados) e Isacar (Jos 19:22). El nombre probablemente refleja un santuario solar cananeo preisraelita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86638, 'spa', 'Pabellón palaciego', 'Estructura ajardinada o pabellón en la corte persa. Aparece tres veces en Ester para describir el espacio real de jardín en Susa: «el patio del jardín del pabellón del palacio» (Ester 1:5) y «el jardín del pabellón» adonde el rey se retira durante la caída de Amán (Ester 7:7-8). Algunas traducciones lo vierten como «palacio» o «atrio», pero su significado arquitectónico apunta a un edificio de jardín.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86640, 'spa', 'Árbol de bálsamo', 'Árbol de bálsamo o morera, conocido por su resina goteante, que aparece solo en plural (בְּכָאִים). En 2 Samuel 5:23-24 y 1 Crónicas 14:14-15, Dios ordena a David usar una arboleda de estos árboles como cobertura táctica, con el susurro de sus copas como señal para avanzar. La forma singular aparece en el Salmo 84:7 en referencia al ''Valle de Bacá.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86641, 'spa', 'llorar, derramar lágrimas (Qal)', 'Forma Qal que cubre el llanto intransitivo en todos sus registros: dolor (Gn 37:35, Abraham llora por Sara), alegría (Gn 33:4, reencuentro de Jacob y Esaú), súplica (Jue 20:23, Israel llora ante el Señor) y angustia ante la pérdida inminente (Gn 21:16, Agar llora en el desierto). Es con diferencia el sentido dominante, con 112 ocurrencias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86660, 'spa', 'llanto intensificado (nominal)', 'Par de ocurrencias (2 R 20:3; Is 38:3) donde el llanto aparece en forma participial o nominal como parte de la súplica de Ezequías ante Dios: «lloré con gran llanto». Las glosas multilingües muestran formas nominales (español «llanto»), lo que sugiere una construcción de acusativo cognado intensificador más que un sentido semántico distinto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86668, 'spa', 'plañir, lamentar por (Piel)', 'Forma Piel intensiva-transitiva: plañir, lamentar o hacer duelo por alguien específicamente. Jeremías 31:15 describe a Raquel llorando «por sus hijos», y Ezequiel 8:14 retrata a mujeres llorando «por Tamuz». El Piel dirige el duelo hacia un objeto particular de dolor, a diferencia del Qal intransitivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86693, 'spa', 'primogénito', 'El primer descendiente nacido de un progenitor, humano o animal, portador de los derechos de primacía incluyendo la doble porción de herencia (Dt 21:17). La narrativa del éxodo gira en torno al primogénito: Dios hiere a los primogénitos de Egipto (Éx 12:29) y reclama los de Israel (Éx 13:2), estableciendo la sustitución levítica (Nm 3:12-13) y la obligación de redimir a los primogénitos (Nm 18:15-16). Figuradamente, בְּכוֹר expresa preeminencia suprema.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86713, 'spa', 'Primicias (ofrenda/producto) — La primera porción de grano, fruto o pan que madu', 'Primicias (ofrenda/producto) — La primera porción de grano, fruto o pan que madura en una temporada dada, presentada a Dios como ofrenda o tributo. Este sentido domina la legislación cultual de Éxodo 23, 34, Levítico 2 y 23, y Números 18 y 28. El término funciona como sustantivo colectivo que abarca trigo, cebada y otros productos, todos consagrados por su prioridad cronológica y dedicación ritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86717, 'spa', 'Fruto de maduración temprana (higo) — Un higo o fruto concretamente de maduració', 'Fruto de maduración temprana (higo) — Un higo o fruto concretamente de maduración temprana, usado de manera literal o en símil vívido. En Números 13:20 se les dice a los espías que verifiquen si la tierra tiene productos tempranos; en Nahúm 3:12 las fortalezas se comparan con higueras cuyos primeros higos caen con solo sacudirlas; e Isaías 28:4 usa la forma femenina en una imagen impactante de la gloria marchita de Efraín.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86725, 'spa', 'Las crías primogénitas del ganado, ofrecidas como dones consagrados a Dios', 'Las crías primogénitas del ganado, ofrecidas como dones consagrados a Dios. Aquí la morfología cambia al plural masculino constructo (בְּכֹרֹת). La ofrenda de Abel de las primicias de su rebaño (Gn 4:4) es la primera atestiguación, mientras que las instrucciones cultuales de Deuteronomio (Dt 12:6, 17; 14:23) regulan su presentación en el lugar elegido por Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86726, 'spa', 'El estatus legal abstracto y los derechos de herencia del hijo primogénito, que ', 'El estatus legal abstracto y los derechos de herencia del hijo primogénito, que abarca la doble porción del patrimonio y la jefatura familiar. El término es central en la rivalidad entre Esaú y Jacob (Gn 25:31-34), donde Esaú vende su primogenitura por un guiso, y en la pérdida del estatus de Rubén (1 Cr 5:1-2). En Génesis 43:33, los hermanos se sientan según su primogenitura, confirmando su función jurídica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86738, 'spa', 'El acto o sonido audible de llorar, ya sea por dolor personal, duelo comunitario', 'El acto o sonido audible de llorar, ya sea por dolor personal, duelo comunitario o súplica penitencial. José ''dio su voz en llanto'' de modo que los egipcios lo oyeron (Gn 45:2); Israel lloró treinta días por Moisés (Dt 34:8); Jeremías promete que Dios convertirá el llanto en gozo (Jer 31:16). A menudo acompañado de אֵבֶל (duelo), צוֹם (ayuno) y מִסְפֵּד (lamentación) como en Est 4:3. En español ''llanto'' y ''lloro'' captan la cualidad vocal y demostrativa que distingue בְּכִי de formas más silenciosas de tristeza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86756, 'spa', 'La primogénita', 'La hija primogénita o mayor, empleada en contextos donde el orden de nacimiento conlleva peso social, legal o narrativo. En Gen 19:31-37, la bekhirah de Lot toma la iniciativa en el episodio de la cueva, reflejando la prerrogativa habitual de la primogénita. En Gen 29:26, Labán apela a la convención de que la hija mayor debe casarse primero, bloqueando el deseo de Jacob por Raquel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86759, 'spa', 'Primogenitura y precocidad', 'Dar fruto temprano o primerizo, designar como primogénito, o experimentar un primer parto. El Piel en Ezequiel 47:12 describe árboles milagrosos que ''dan fruto temprano'' cada mes. En Deuteronomio 21:16, un padre no puede ''dar la primogenitura'' a un hijo menor por encima del primogénito legítimo. El participio Hifil en Jeremías 4:31 retrata los dolores de una primeriza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86761, 'spa', 'Nombre propio masculino', 'Nombre propio masculino que significa ''camello joven'', aplicado a dos personajes del Antiguo Testamento: (a) un hijo de Benjamín (Gn 46:21; 1 Cr 7:6, 8), y (b) un hijo de Efraín (Nm 26:35), identificado con Bered en 1 Crónicas 7:20. El cognado asirio bakru confirma la raíz semántica de ''primogénito/joven'' que fundamenta este nombre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86765, 'spa', 'Bicri (nombre propio)', 'Nombre propio de un hombre benjaminita, conocido únicamente como padre de Seba, quien dirigió una breve secesión tribal contra la monarquía restaurada de David (2 Sam 20:1–22). La frase «Seba hijo de Bicri» se repite ocho veces en ese único capítulo, subrayando la gravedad de la rebelión. El nombre probablemente deriva de bekor («primogénito») y puede tener el sentido de «joven».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86767, 'spa', 'No (negación poética) — partícula de negación poética que funciona de modo idént', 'No (negación poética) — partícula de negación poética que funciona de modo idéntico a לֹא (''no'') pero reservada para un registro literario elevado. Se encuentra casi exclusivamente en los Salmos (Sal 10:4, 6, 11; 16:8; 21:7; 46:5), Isaías (Is 26:10-18; 33:20-24; 44:8-9), Proverbios y Oseas. A menudo se repite con efecto retórico en secuencias prolongadas de negación o certeza. Su distinción respecto a לֹא es puramente estilística: todas las lenguas de destino la traducen con el mismo ''no''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86775, 'spa', 'Deidad babilónica', 'La deidad principal de Babilonia, objeto de burla por parte de los profetas de Israel como un dios impotente. Isaías lo retrata inclinándose y postrándose mientras su ídolo es cargado sobre animales (Isaías 46:1). Jeremías anuncia el juicio: «Publicad entre las naciones… Bel es avergonzado» (Jeremías 50:2) y «Castigaré a Bel», quien deberá vomitar lo que devoró (Jeremías 51:44). El colapso de Bel simboliza la caída de Babilonia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86779, 'spa', 'Brillar o sonreír', 'Mostrar un brillo o sonrisa, parecer alegre. Usado en Job 9:27, 10:20 y Salmo 39:13, donde el sufriente anhela ''alegrarse'' antes de morir. En Amós 5:9, la misma raíz toma un giro sombrío: Dios hace que la ruina ''destelle'' o ''irrumpa'' sobre el fuerte (הַמַּבְלִיג שֹׁד עַל־עָז), transformando la imagen de luz en instrumento de juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86780, 'spa', 'Nombre sacerdotal', 'Nombre sacerdotal presente en contextos davídicos y posexílicos. Bilga dirigió la decimoquinta división de sacerdotes (1 Crónicas 24:14). Un sacerdote con este nombre regresó con Zorobabel (Nehemías 12:5), y la familia participó después en la renovación del pacto (Nehemías 12:18). Su reaparición a lo largo de los siglos sugiere un linaje sacerdotal perdurable que sobrevivió al exilio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86782, 'spa', 'Amigo de Job', 'Nombre propio masculino que designa a uno de los tres amigos de Job, identificado como ''el suhita'' (Job 2:11; 8:1; 18:1; 25:1; 42:9). El nombre probablemente significa ''Bel ha amado'' (cf. cuneiforme Bir-Dadda), reflejando la onomástica teofórica mesopotámica. Los discursos de Bildad defienden una teología retributiva estricta, insistiendo en que los justos nunca son abandonados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86783, 'spa', 'Gastarse, envejecer (Qal) — Gastarse o deteriorarse intransitivamente, dicho de ', 'Gastarse, envejecer (Qal) — Gastarse o deteriorarse intransitivamente, dicho de vestiduras, sandalias, el cuerpo humano e incluso el cosmos que se desgasta con el tiempo. La promesa del desierto en Deuteronomio de que las ropas y sandalias no se gastaron (Dt 8:4; 29:5; Neh 9:21) le da a la palabra su marco más emblemático. Isaías y los Salmos lo extienden cósmicamente: los cielos se gastarán ''como un vestido'' (Sal 102:26; Is 51:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86790, 'spa', 'Consumir, desgastar (Piel causativo) — Consumir, deteriorar o desgastar transiti', 'Consumir, desgastar (Piel causativo) — Consumir, deteriorar o desgastar transitivamente, el Piel causativo donde un agente inflige deterioro sobre otro. Dios consume la carne y la piel de Jeremías (Lm 3:4); los malvados ''desgastan'' al pueblo de Dios (1 Cr 17:9); la forma del cuerpo se consume en el Seol (Sal 49:14). Tres ocurrencias llevan esta fuerza intensificada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86795, 'spa', 'Pasar, disfrutar (Piel) — Un desarrollo semántico llamativo de ''consumir'' a ''apr', 'Pasar, disfrutar (Piel) — Un desarrollo semántico llamativo de ''consumir'' a ''aprovechar plenamente'' con un matiz positivo. Los malvados ''pasan sus días en prosperidad'' (Job 21:13), y en la nueva creación los escogidos de Dios ''disfrutarán la obra de sus manos'' (Is 65:22). Un contraste vívido con los sentidos de deterioro, revelando cuán completamente puede redirigirse la valencia de la palabra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86798, 'spa', 'Desgastado o deteriorado', 'Fisicamente gastado, raido o deteriorado por el uso prolongado. Aplicado a objetos materiales en la narrativa del engano gabaonita: sacos, odres, sandalias y vestiduras elegidos deliberadamente para aparentar vejez y desgaste por el viaje (Jos 9:4-5). Tambien usado figuradamente de una mujer agotada por la vida inmoral (Ez 23:43; cf. el uso del verbo afin por Sara en Gn 18:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86801, 'spa', 'Sierva personal de Raquel (שִׁפְחָה), entregada a Jacob como esposa-concubina cu', 'Sierva personal de Raquel (שִׁפְחָה), entregada a Jacob como esposa-concubina cuando Raquel no podía concebir. Madre de Dan y Neftalí (Gn 30:3-8). Labán entregó a Bilha a Raquel al momento del matrimonio (Gn 29:29). El relato de la violación de Bilha por Rubén (Gn 35:22) resuena en el oráculo de Jacob en su lecho de muerte (Gn 49:4) y en la genealogía del Cronista (1 Cr 5:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86804, 'spa', 'Terror, calamidad repentina — Pavor extremo, calamidad súbita o terror abrumador', 'Terror, calamidad repentina — Pavor extremo, calamidad súbita o terror abrumador, usado para los horrores que alcanzan al malvado (Job 18:11, 14; 24:17; 27:20), la angustia existencial del que sufre (Sal 73:19) y la aniquilación total de ciudades orgullosas en el juicio profético (Ez 26:21; 27:36; 28:19). El ''rey de los espantos'' en Job 18:14 es una impactante personificación de la muerte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86808, 'spa', 'Nombre propio', 'Nombre propio que posiblemente significa ''modesto'' o ''débil'', llevado por dos individuos distintos. El horita בִּלְהָן (Gn 36:27; 1 Cr 1:42) pertenece a los clanes autóctonos de Seír absorbidos por Edom. El benjamita בִּלְהָן (1 Cr 7:10) encabeza una familia que reunió 17.200 guerreros. Todas las tradiciones de traducción simplemente transliteran el nombre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86809, 'spa', 'Tributo imperial', 'Impuesto o tributo dentro del sistema fiscal persa. Aparece en la frase «מִנְדָּה, בְּלוֹ y הֲלָךְ» (tributo, contribución y peaje) tres veces en Esdras (4:13, 20; 7:24). Funcionarios provinciales advierten que una Jerusalén reconstruida se negará a pagar el «tributo» (Esdras 4:13), y Artajerjes confirma las obligaciones fiscales históricas de la ciudad (Esdras 4:20) pero exime a los servidores del templo (Esdras 7:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86810, 'spa', 'Harapos como acolchado', 'Prendas raídas o harapos utilizados como protección. Ebed-melec toma «ropa vieja» del almacén y la baja a Jeremías en la cisterna, indicándole que «se ponga estos trapos gastados bajo las axilas» para evitar que las cuerdas lo lastimen (Jeremías 38:11-12). La mención específica de telas viejas resalta tanto la indignidad de la situación de Jeremías como la bondad ingeniosa del etíope.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86812, 'spa', 'Beltsasar (nombre cortesano)', 'Nombre de corte babilónico otorgado al profeta hebreo Daniel durante su servicio en la corte de Nabucodonosor. Aparece en Daniel 2:26; 4:8–9, 18–19; 5:12, siempre en discursos reales o presentaciones oficiales. El nombre (del acadio Balat-su-usur, «protege su vida») señala la doble identidad de Daniel como israelita fiel y sabio babilónico reconocido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86813, 'spa', 'Sin, no, por falta de — el uso dominante en 57 ocurrencias, funcionando como pre', 'Sin, no, por falta de — el uso dominante en 57 ocurrencias, funcionando como preposición o adverbio que significa ''sin'', ''no'' o ''por falta de''. En Gn 31:20 niega un verbo finito en prosa (בְּלִי הִגִּיד ''sin decir''), mientras que en Job gobierna sustantivos con frecuencia para expresar privación (Job 8:11 בְּלִי־מַיִם ''sin agua''). Las traducciones multilingües convergen en ''sin/sans/ohne'', confirmando el sentido universal de privación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86822, 'spa', 'Nada, destrucción — un uso sustantival raro (1 vez) en Is 38', 'Nada, destrucción — un uso sustantival raro (1 vez) en Is 38:17, donde בְּלִי adquiere fuerza concreta como ''nada'' o ''destrucción'' en la frase שַׁחַת בְּלִי ''fosa de aniquilación''. Este uso se apoya en la raíz etimológica que significa ''desgastarse'' (cf. árabe بِلًى), tratando el destino del Seol no como mera ausencia sino como disolución activa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86829, 'spa', 'Pienso mezclado', 'Alimento preparado para ganado y asnos, mezcla de grano y hierba. Job pregunta si los animales se quejan cuando tienen forraje (Job 6:5) y describe a los pobres cosechando בְּלִיל en los campos (Job 24:6). Isaías vislumbra un tiempo en que los animales de labor comerán ''forraje sazonado'' (Isaías 30:24), señal de prosperidad agrícola. El término implica alimento preparado, no simple pastoreo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86831, 'spa', 'Inutilidad moral o maldad, que caracteriza a personas despreciables (''hijos de B', 'Inutilidad moral o maldad, que caracteriza a personas despreciables (''hijos de Belial,'' Dt 13:13; Jue 19:22; 1 S 2:12; 1 R 21:10, 13) y actos perversos (''palabra/cosa de Belial,'' Sal 41:8; 101:3; Dt 15:9). También aparece en imágenes casi mitológicas como ''torrentes de Belial'' que amenazan al salmista con la muerte (2 S 22:5; Sal 18:4). La expresión funcionaba como marca moral en contextos de pacto y juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86847, 'spa', 'El sentido cúltico-técnico dominante', 'El sentido cúltico-técnico dominante: ofrendas de grano mezcladas con aceite. Casi todas las apariciones (38 de 42) emplean el participio pasivo Qal bĕlûlāh en las prescripciones sacrificiales de la fuente sacerdotal — ''flor de harina mezclada con aceite'' (Lv 2:4-5; Nm 7:13ss.). Este uso formulario se extiende desde Éx 29:2 por todo Levítico y Números.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86848, 'spa', 'Confundir o trastornar el lenguaje — la famosa etimología de Babel', 'Confundir o trastornar el lenguaje — la famosa etimología de Babel. En Gn 11:7 Dios dice ''confundamos su lengua'' (cohortativo nāvĕlāh), y Gn 11:9 deriva el nombre Babel de este acto de confusión. Solo dos apariciones portan este sentido, pero le dieron al vocablo su fama imperecedera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86849, 'spa', 'Ser ungido o humedecido con aceite, sentido raro atestiguado únicamente en Sal 9', 'Ser ungido o humedecido con aceite, sentido raro atestiguado únicamente en Sal 92:10 (Heb. 92:11): ''he sido ungido (ballōtî) con aceite fresco''. Esto conecta con el cognado árabe balla (''humedecer'') y puede representar la capa más antigua del significado de la raíz — mojadura física más que mezcla completa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86850, 'spa', 'Mezclarse reflexivamente entre los pueblos, atestiguado solo en el Hitpael en Os', 'Mezclarse reflexivamente entre los pueblos, atestiguado solo en el Hitpael en Os 7:8: ''Efraín se mezcla (yitbôlāl) entre las naciones''. El tallo Hitpael le confiere una cualidad deliberada y autoiniciada — no asimilación pasiva, sino mezcla cultural voluntaria. Oseas emplea esto metafóricamente para condenar la pérdida de identidad distintiva de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86856, 'spa', 'Tragar (Qal físico) — el sentido básico activo del Qal de tragar o engullir físi', 'Tragar (Qal físico) — el sentido básico activo del Qal de tragar o engullir físicamente (21 ocurrencias). La vara de Aarón ''tragó'' las varas de los magos (Éx 7:12), la tierra ''tragó'' a la compañía de Coré (Nm 16:30, 32; Dt 11:6), y las vacas flacas del faraón ''tragaron'' a las gordas en el sueño (Gn 41:7, 24). El mar ''tragó'' a Egipto en el Éxodo (Éx 15:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86857, 'spa', 'Devorar, tragar (Piel intensivo) — el tronco Piel expresando una deglución forzo', 'Devorar, tragar (Piel intensivo) — el tronco Piel expresando una deglución forzosa o un devorar abrumador (15 ocurrencias), donde la acción es más deliberada e intensa que el Qal básico. Nabucodonosor ''me ha devorado como un dragón'' (Jer 51:34), los enemigos ''devoran'' a Israel (Sal 124:3), y el fuego ''devora'' a los malvados (Sal 21:9). El Piel retiene la imagen de tragar pero intensifica la fuerza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86867, 'spa', 'Destruir, aniquilar (Piel metafórico) — sentido Piel plenamente metafórico que s', 'Destruir, aniquilar (Piel metafórico) — sentido Piel plenamente metafórico que significa destruir o aniquilar (5 ocurrencias), donde la imagen de tragar se ha desvanecido y queda la destrucción pura. Job 2:3 presenta a Dios diciendo a Satanás ''me incitaste contra él para destruirlo sin causa''. Isaías 25:7-8 promete que Dios ''destruirá el velo que cubre a todos los pueblos'' y ''devorará la muerte para siempre''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86874, 'spa', 'Ser tragado (Nifal/Pual pasivo) — troncos pasivos Nifal y Pual (5 ocurrencias) q', 'Ser tragado (Nifal/Pual pasivo) — troncos pasivos Nifal y Pual (5 ocurrencias) que expresan el estado de ser tragado, consumido o abrumado. Se advierte al ejército de David que no se quede en los vados ''para que el rey no sea tragado'' (2 S 17:16), Israel ha sido ''devorado entre las naciones'' (Os 8:8), y los profetas borrachos están ''confundidos por el vino'' (Is 28:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86881, 'spa', 'Tambalearse, ser engullido (Hitpael reflexivo) — una única ocurrencia Hitpael re', 'Tambalearse, ser engullido (Hitpael reflexivo) — una única ocurrencia Hitpael reflexiva (Sal 107:27) que describe a marineros que ''se tambalean'' o ''son engullidos'' en una tormenta: ''toda su sabiduría fue tragada'', es decir, su destreza náutica quedó anulada e inútil. El sentido tiende un puente entre tragar y confundir: la tormenta ''traga'' su habilidad, dejándolos aturdidos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86883, 'spa', 'Confundir, desconcertar (Piel) — un sentido Piel distintivo de confundir, descon', 'Confundir, desconcertar (Piel) — un sentido Piel distintivo de confundir, desconcertar o extraviar (3 ocurrencias), notable desarrollo semántico donde tragar el discurso o el juicio de alguien produce perplejidad. David ora ''confunde sus lenguas'' (Sal 55:9), Isaías acusa a los líderes de Israel de ''confundir'' al pueblo (Is 3:12), y el consejo de Egipto ''será confundido'' (Is 19:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86901, 'spa', 'Bela', 'Nombre propio que designa a (a) Bela hijo de Beor, rey de Edom que reinó en Dinaba (Gn 36:32; 1 Cr 1:43), y (b) Bela hijo de Benjamín (Gn 46:21; Nm 26:38; 1 Cr 7:6; 8:1). También es el nombre antiguo de Zoar (Gn 14:2). El español, el francés y el alemán transliteran uniformemente como Bela sin subdivisión semántica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86906, 'spa', 'Aparte de / además de / sin — Partícula preposicional que expresa exclusión, sep', 'Aparte de / además de / sin — Partícula preposicional que expresa exclusión, separación o ausencia. Se usa con sufijos para marcar lo que se excluye o aparta: Faraón declara que nadie actuará bil''adekha (''sin ti'', Gn 41:44); Dios afirma ein bil''aday (''no hay otro fuera de mí'', Is 45:6). Aparece en contextos tanto legal-narrativos como profético-teológicos, afirmando frecuentemente la exclusividad divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86919, 'spa', 'Balaam (nombre propio) — nombre propio del profeta/adivino mesopotámico, hijo de', 'Balaam (nombre propio) — nombre propio del profeta/adivino mesopotámico, hijo de Beor, contratado por Balac de Moab para maldecir a Israel pero repetidamente obligado por Dios a bendecirlo (Nm 22-24). El ciclo de Balaam incluye el célebre episodio del asna que habla (Nm 22:28) y el oráculo mesiánico de la estrella (Nm 24:17). Textos posteriores lo condenan por el consejo que llevó a Israel a la idolatría en Baal-Peor (Nm 31:16; cf. 2 P 2:15; Ap 2:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86925, 'spa', 'El nombre propio del rey moabita que contrató a Balaam', 'El nombre propio del rey moabita que contrató a Balaam. Las 43 apariciones se concentran en Números 22-24 (la narrativa de Balaam), con menciones retrospectivas en Josué 24:9, Jueces 11:25 y Miqueas 6:5. Las traducciones transliteran uniformemente el nombre (Balac/Balak), confirmando un referente único de nombre propio sin extensión semántica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86930, 'spa', 'Belsasar (rey babilonio)', 'Nombre propio del último rey babilonio según se presenta en Daniel. Todas las tradiciones de traducción preservan el nombre mediante transliteración — español ''Belsasar'', francés ''Beltschatsar'', alemán ''Belsazar'' — con variaciones fonéticas menores que reflejan la adaptación de cada lengua al nombre teofórico acadio. Las dos formas ortográficas en Daniel (בֵּלְשַׁאצַּר en 5:1-29 y בֵּלְאשַׁצַּר en 7:1; 8:1) designan a la misma persona.');